-- World tables whose layout differs between the database versions. Each
-- column follows the version that the current server uses.

BEGIN;

CREATE SCHEMA IF NOT EXISTS "world";

CREATE TABLE "world"."commission" (
    "commission_id" bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL,
    "char_id" integer NOT NULL,
    "buyer_id" integer,
    "item_name" varchar(100) NOT NULL,
    "item_price" bigint NOT NULL,
    "item_commission_type" integer NOT NULL,
    "item_commission_first_type" integer NOT NULL,
    "commission_fee" bigint NOT NULL,
    "item_commission_expired_type" integer NOT NULL,
    "item_expired_time" integer NOT NULL,
    "char_name" varchar(30) NOT NULL,
    "item_id" integer NOT NULL,
    "item_grade" integer NOT NULL,
    "item_general" integer NOT NULL,
    "item_register_time" timestamp without time zone,
    "item_delete_time" timestamp without time zone,
    "item_classid" integer NOT NULL,
    "discount_type" integer NOT NULL,
    CONSTRAINT "pk_commission" PRIMARY KEY ("commission_id")
);

CREATE TABLE "world"."item_auction" (
    "auction_id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL,
    "auction_status" smallint DEFAULT 0 NOT NULL,
    "extend_status" smallint DEFAULT 0 NOT NULL,
    "auction_npc" integer DEFAULT 0 NOT NULL,
    "start_time" integer NOT NULL,
    "end_time" integer NOT NULL,
    "item_index" integer NOT NULL,
    "item_type" integer NOT NULL,
    "init_price" bigint DEFAULT 0 NOT NULL,
    "item_amount" bigint DEFAULT 0 NOT NULL,
    "next_item_type" integer DEFAULT 0 NOT NULL,
    "next_init_price" bigint DEFAULT 0 NOT NULL,
    "next_item_amount" bigint DEFAULT 0 NOT NULL,
    "next_auction_display_start" integer NOT NULL,
    CONSTRAINT "ck_item_auction_auction_status_tinyint" CHECK ("auction_status" BETWEEN 0 AND 255),
    CONSTRAINT "ck_item_auction_extend_status_tinyint" CHECK ("extend_status" BETWEEN 0 AND 255),
    CONSTRAINT "pk_item_auction" PRIMARY KEY ("auction_id")
);

COMMIT;
